# Code generated by Claude
"""
Keyboard teleop for the AgileX Tracer base, with true hold-to-drive,
variable-speed controls. Change SCENE_PATH below to drive in a different
scene -- no flags needed, same pattern as wave_chemistry_lab.py.

Uses a raw GLFW window + mujoco's low-level rendering calls instead of
mujoco.viewer.launch_passive, because launch_passive's key_callback only
fires on key press with no release event -- there's no way to detect "key
still held" through it. Polling glfw.get_key() every frame gives instant,
correct press/release state, the same technique games use for movement.

Trade-off: launch_passive gives you free mouse-orbit camera control out of
the box; this raw-GLFW version doesn't include that (camera just follows
the robot instead).

Controls (cruise-control style -- holding a key keeps accelerating in that
direction up to MAX_CMD; release to hold the current speed; tap the
opposite key to slow down/reverse):
    W / Up Arrow    - accelerate forward
    S / Down Arrow  - accelerate backward
    A / Left Arrow  - accelerate turn-left
    D / Right Arrow - accelerate turn-right
    Esc             - quit

Setup:
    pip install glfw

Run from project root:
    python experiments/keyboard_drive_tracer.py
"""

import math
from pathlib import Path

import glfw
import mujoco

PROJECT_ROOT = Path(__file__).resolve().parent.parent

# --- Change these two to drive somewhere else ---
SCENE_PATH = PROJECT_ROOT / "models" / "scenes" / "chemistry_lab_tracer.xml"
# North-central gap between the bench and the storage cabinet/rolling cart --
# ~2.5-3m clearance on every side (computed from their positions in the
# scene XML), vs. ~1.6m at the old arm-robot spawn point right by the bench.
SPAWN_POS = [-1.0, 3.5, 0.22]   # z = wheel-center height; None to use the XML's own pose

WARMUP_STEPS = 500  # let contacts settle before driving -- see wave_chemistry_lab.py

INCR = 0.1          # per-frame accel increment while a key is held
MAX_CMD = 1.0         # matches actuator ctrlrange [-1, 1]
TURN_SCALE = 0.6     # relative weight of turning vs. forward command; tune to taste
CAM_DISTANCE = 2.5
CAM_ELEVATION = -60
FOVY_DEG = 90  # wider than MuJoCo's ~45 default so surroundings stay visible


def mix_to_wheel_ctrl(linear: float, angular: float) -> tuple[float, float]:
    """Differential-drive mixing, same convention as the real robot's
    /cmd_vel (positive angular = turn left).
    Returns: target activation for left and right actuators."""
    left = linear - TURN_SCALE * angular
    right = linear + TURN_SCALE * angular
    scale = max(1.0, abs(left), abs(right))
    return (MAX_CMD * left / scale, MAX_CMD * right / scale)


def main():
    model = mujoco.MjModel.from_xml_path(str(SCENE_PATH))
    model.vis.global_.fovy = FOVY_DEG
    data = mujoco.MjData(model)

    left_id = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR, "left_motor")
    right_id = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR, "right_motor")
    base_id = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_BODY, "base_link")
    if left_id < 0 or right_id < 0:
        raise RuntimeError("Could not find left_motor / right_motor actuators in model.")
    if base_id < 0:
        raise RuntimeError("Could not find base_link body in model.")

    robot_mass = model.body_subtreemass[base_id]
    print(f"Tracer subtree mass: {robot_mass:.2f} kg  "
          f"(max drive force/wheel = 10 gear x 1.0 ctrl / 0.13m radius = 76.9 N)")

    # Sanity-check mesh scale: real Tracer geoms should be centimeter-to-meter
    # scale. A bounding radius in the tens/hundreds of meters means the STL
    # was likely authored in millimeters and is being read as meters.
    for geom_name in ["base_link_geom", "right_link_geom", "left_Link_geom"]:
        gid = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_GEOM, geom_name)
        if gid >= 0:
            print(f"  {geom_name}: bounding radius = {model.geom_rbound[gid]:.4f} m")

    if SPAWN_POS is not None:
        data.qpos[0:3] = SPAWN_POS
        mujoco.mj_forward(model, data)

    print("Settling physics...")
    for _ in range(WARMUP_STEPS):
        data.ctrl[:] = 0.0
        mujoco.mj_step(model, data)
    print(f"Robot settled at {data.qpos[0:3]}  (spawn target was {SPAWN_POS})")

    if not glfw.init():
        raise RuntimeError("Could not initialize GLFW")
    window = glfw.create_window(1200, 900, "Tracer Keyboard Drive", None, None)
    glfw.make_context_current(window)
    glfw.swap_interval(1)

    cam = mujoco.MjvCamera()
    opt = mujoco.MjvOption()
    mujoco.mjv_defaultCamera(cam)
    mujoco.mjv_defaultOption(opt)
    cam.distance, cam.elevation, cam.azimuth = CAM_DISTANCE, CAM_ELEVATION, 90

    scene = mujoco.MjvScene(model, maxgeom=10000)
    context = mujoco.MjrContext(model, mujoco.mjtFontScale.mjFONTSCALE_150)

    SUBSTEPS = max(1, round((1.0 / 60.0) / model.opt.timestep))
    print(f"Stepping physics {SUBSTEPS}x per rendered frame "
          f"({model.opt.timestep}s each) to keep pace with real time.")

    def held(key):
        return glfw.get_key(window, key) == glfw.PRESS

    linear = 0.0
    angular = 0.0
    frame = 0
    while not glfw.window_should_close(window):
        linear += (INCR if held(glfw.KEY_W) or held(glfw.KEY_UP) else 0.0) \
                 - (INCR if held(glfw.KEY_S) or held(glfw.KEY_DOWN) else 0.0)
        angular += (INCR if held(glfw.KEY_A) or held(glfw.KEY_LEFT) else 0.0) \
                  - (INCR if held(glfw.KEY_D) or held(glfw.KEY_RIGHT) else 0.0)
        linear = max(-MAX_CMD, min(linear, MAX_CMD))
        angular = max(-MAX_CMD, min(angular, MAX_CMD))

        left_ctrl, right_ctrl = mix_to_wheel_ctrl(linear, angular)
        # left_joint's world-frame rotation axis is mirrored relative to
        # right_joint (their bodies are mounted as mirror images, both using
        # local axis="0 0 1"), so identical ctrl on both spins them in
        # opposite senses -- negate left to compensate, without touching
        # Tracer.xml's own gear value.
        data.ctrl[left_id] = -left_ctrl
        data.ctrl[right_id] = right_ctrl

        # Advance physics enough sub-steps to keep pace with real time --
        # one mj_step() per render frame under-steps since model timestep
        # (0.002s) is much finer than the ~60Hz render/vsync rate.
        for _ in range(SUBSTEPS):
            mujoco.mj_step(model, data)
        cam.lookat[:] = data.xpos[base_id]

        # Keep the camera behind the robot's heading instead of a fixed
        # compass direction, so turning doesn't leave you looking sideways.
        qw, qx, qy, qz = data.xquat[base_id]
        yaw_deg = math.degrees(math.atan2(2 * (qw * qz + qx * qy),
                                           1 - 2 * (qy * qy + qz * qz)))
        cam.azimuth = yaw_deg + 90  # offset may need flipping/tuning once you see it

        width, height = glfw.get_framebuffer_size(window)
        viewport = mujoco.MjrRect(0, 0, width, height)
        mujoco.mjv_updateScene(model, data, opt, None, cam, mujoco.mjtCatBit.mjCAT_ALL, scene)
        mujoco.mjr_render(viewport, scene, context)

        glfw.swap_buffers(window)
        glfw.poll_events()

        frame += 1
        if frame % 60 == 0:
            print(f"pos={data.qpos[0:3].round(2)}  "
                  f"ctrl=({data.ctrl[left_id]:.2f}, {data.ctrl[right_id]:.2f})  "
                  f"cmd=(lin={linear:.2f}, ang={angular:.2f})")

        if held(glfw.KEY_ESCAPE):
            break

    glfw.terminate()


if __name__ == "__main__":
    main()